from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in seen:
                seen.add((r, c))
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in seen:
                seen.add((r, c))
                queue.append((r, c))
    directions = ((-1, 0), (1, 0), (0, -1), (0, 1))
    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr, nc) not in seen:
                seen.add((nr, nc))
                queue.append((nr, nc))

    out = [row[:] for row in grid]
    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] != background or (r0, c0) in seen:
                continue
            component = []
            seen.add((r0, c0))
            queue.append((r0, c0))
            while queue:
                r, c = queue.popleft()
                component.append((r, c))
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
            fill = 7 if len(component) % 2 else 2
            for r, c in component:
                out[r][c] = fill
    return out

